insert into questions (external_key, question_type, question_text, instructions, media, correct_answer, score_config, difficulty, category, tags, time_limit_seconds, required) values ('vrm-rc-01', ('multiple_choice')::question_type, 'Passage: "Urban planners have increasingly turned to ''road diets'' — reducing the number of travel lanes on a street to make room for bike lanes, wider sidewalks, or turn lanes — as a tool for improving traffic safety. Counterintuitively, studies in several cities have found that these changes did not significantly increase congestion, even though the same volume of vehicles now had less road to use. Researchers attribute this partly to drivers adjusting their routes and departure times, and partly to the removed lanes having been used inefficiently for passing and weaving rather than genuine capacity." According to the passage, why didn''t road diets significantly increase congestion?', NULL, ('[]')::jsonb, NULL, ('[]')::jsonb, ('medium')::assessment_difficulty, 'verbal-reasoning-mastery', '{}'::text[], NULL, true)
