insert into questions (external_key, question_type, question_text, instructions, media, correct_answer, score_config, difficulty, category, tags, time_limit_seconds, required) values ('vrm-rc-07', ('multiple_choice')::question_type, 'Passage: "When a company announces layoffs, its stock price often rises in the following days — a pattern that seems to conflict with the intuition that losing experienced staff should hurt a company''s prospects. Analysts explain this by pointing out that markets respond less to the layoffs themselves than to what they signal: that management is taking decisive action on costs, which investors read as a sign of financial discipline, especially if the company had been under pressure to control spending." The passage explains the stock-price pattern primarily as a result of:', NULL, ('[]')::jsonb, NULL, ('[]')::jsonb, ('hard')::assessment_difficulty, 'verbal-reasoning-mastery', '{}'::text[], NULL, true)
