insert into questions (external_key, question_type, question_text, instructions, media, correct_answer, score_config, difficulty, category, tags, time_limit_seconds, required) values ('vrm-rc-09', ('multiple_choice')::question_type, 'Passage: "Muscle memory is something of a misnomer: skills like riding a bicycle or typing are not stored in the muscles themselves but in neural pathways built through repeated practice. Once these pathways are well established, the movements become more automatic, requiring less conscious attention. This is why a skill practiced heavily years ago, even if unused for a long time, is typically relearned far faster than it was learned the first time." According to the passage, ''muscle memory'' is misleading because:', NULL, ('[]')::jsonb, NULL, ('[]')::jsonb, ('medium')::assessment_difficulty, 'verbal-reasoning-mastery', '{}'::text[], NULL, true)
