insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('verbal-reasoning-mastery', 'Verbal Reasoning Mastery', 'An advanced-tier follow-on to Verbal Reasoning, pushing into denser passages and multi-step argument chains.', 'Verbal Reasoning Mastery is built around the three question types that make up the GRE General Test''s Verbal Reasoning measure — one of the most widely used graduate-admissions verbal assessments: Text Completion (fill a blank using context and vocabulary), Sentence Equivalence (pick two answers that complete a sentence equivalently), and Reading Comprehension (short passages with inference questions).', 'message-square', (select id from assessment_categories where key = 'language'), ('timed_questionnaire')::assessment_engine_type, ('hard')::assessment_difficulty, 25, 30, false, ('premium')::assessment_access, ('published')::assessment_status)
