insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'verbal-reasoning-mastery'), 'overall', 0, 30, 'Developing', 'Advanced verbal reasoning is still forming — dense vocabulary-in-context and multi-clause passages take significant effort to parse under time pressure.', ARRAY['Read one long-form article daily and summarize its main claim in one sentence', 'Build vocabulary through context (guess the meaning, then check) rather than flashcard memorization alone', 'Practice text completion untimed first, then reintroduce the clock']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'verbal-reasoning-mastery'), 'overall', 31, 50, 'Average', 'Comfortable with straightforward vocabulary-in-context, but sentence equivalence''s double-correct-answer format and denser passages slow you down.', ARRAY['Practice eliminating obviously-wrong pairs first in sentence equivalence before comparing the remainder', 'Read passages once for structure, then again for the specific inference being asked']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'verbal-reasoning-mastery'), 'overall', 51, 70, 'Strong', 'Reliable across all three formats, occasionally slowed by unfamiliar vocabulary or a passage''s more subtle inference.', ARRAY['Push into denser nonfiction (academic abstracts, opinion essays with counter-arguments) to raise your inference ceiling', 'Time yourself on full timed sets to build stamina, not just accuracy']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'verbal-reasoning-mastery'), 'overall', 71, 85, 'Very Strong', 'Fast and precise across text completion, sentence equivalence, and reading comprehension, rarely tripped up by a distractor that merely sounds plausible.', ARRAY['This level of verbal reasoning transfers directly to graduate-level reading and argument-heavy writing', 'Try passages from unfamiliar academic fields to stress-test comprehension without domain familiarity to lean on']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'verbal-reasoning-mastery'), 'overall', 86, 100, 'Exceptional', 'Expert-level verbal reasoning — vocabulary, equivalence judgments, and passage inference are all handled quickly and precisely under time pressure.', ARRAY['Consider fields that lean heavily on precise written argument — law, editing, research, policy analysis', 'Mentor others on distinguishing a genuinely equivalent word choice from one that merely fits the sentence']::text[], NULL, 5);
